    var endY = sin(phiRad) * rx * cos(th2) + cos(phiRad) * ry * sin(th2) + cy;
    var c2x = endX - rx * cos(phiRad) * (-sin(th2)) * t + ry * sin(phiRad) * (cos(th2)) * t;
    var c2y = endY - rx * sin(phiRad) * (-sin(th2)) * t - ry * cos(phiRad) * (cos(th2)) * t;
