      rep.repeatedCount = group.length;
      rep.itemSamples = itemTexts.slice(0, 5);
      rep._aggregationHint = "Aggregated " + group.length + " similar repeating items to save context tokens. Structure matches representative item.";
      out.push(rep);
      i = j;
